{
  "title": "欧式街头的红色灯笼",
  "summary": "白天时分，两盏红色灯笼悬挂在电线上，背景是蓝天白云与欧式建筑，营造出节日氛围。"
}

{
  "title": "红灯笼下的殖民地街景",
  "summary": "镜头在装饰着红色灯笼的彩色建筑街道上缓慢移动，展示了具有殖民地风格的建筑风貌。"
}

{
  "title": "春节红灯笼特写",
  "summary": "白天拍摄，画面展示了春节期间悬挂的红色灯笼和中国结，充满节日装饰与传统文化氛围。"
}

{
  "title": "金属架上的彩色筷子",
  "summary": "白天，金属架上整齐排列着色彩丰富的筷子，展示了日常用品的商品陈列与美食文化。"
}

{
  "title": "印度寺庙神兽雕像",
  "summary": "白天，镜头聚焦于色彩斑斓的印度教寺庙顶部，一只白色神兽雕像卧在华丽屋顶上，展现宗教艺术景观。"
}

{
  "title": "印度神庙塔门细节",
  "summary": "白天时分，镜头聚焦于色彩斑斓且雕刻精美的印度教神庙塔门，展示了其复杂的建筑细节与宗教文化景观。"
}

{
  "title": "印度寺庙神像特写",
  "summary": "镜头聚焦于色彩斑斓的印度教寺庙顶部，展示了众多雕刻精美的神像与装饰细节。"
}

{
  "title": "车站街道指示牌",
