}

{
  "title": "森林猴子攀爬",
  "summary": "白天，一只猴子在茂密的森林中攀爬树干，展现自然野趣。"
}

{
  "title": "热带花园静谧池塘",
  "summary": "白天时分，热带花园的池塘中睡莲叶漂浮水面，周围绿植茂盛，画面宁静自然。"
}

{
  "title": "绿叶丛中粉花绽放",
